static volatile sig_atomic_t authorization_stop = 0;

static int authorization_block_termination_signals(sigset_t *previous_mask) {
    sigset_t termination_signals;
    if (previous_mask == NULL || sigemptyset(&termination_signals) != 0 ||
        sigaddset(&termination_signals, SIGTERM) != 0 ||
        sigaddset(&termination_signals, SIGINT) != 0) {
        return 0;
    }
    return pthread_sigmask(SIG_BLOCK, &termination_signals, previous_mask) == 0;
}

static int authorization_unblock_termination_signals(void) {
    sigset_t termination_signals;
    if (sigemptyset(&termination_signals) != 0 ||
        sigaddset(&termination_signals, SIGTERM) != 0 ||
        sigaddset(&termination_signals, SIGINT) != 0) {
        return 0;
    }
    return pthread_sigmask(SIG_UNBLOCK, &termination_signals, NULL) == 0;
}

static int authorization_restore_signal_mask(const sigset_t *previous_mask) {
    if (previous_mask == NULL) {
        return 0;
    }
    return pthread_sigmask(SIG_SETMASK, previous_mask, NULL) == 0;
}

static void stop_service(int signal_number) {
    (void)signal_number;
    authorization_stop = 1;
}

static void print_usage(const char *program) {
    (void)fprintf(stderr,
        "usage: %s --check-config --config PATH\n"
        "       %s --serve --config PATH --listen HOST:PORT [--max-requests N] "
        "[--connection-timeout-ms N] [--max-connections N]\n",
        program, program);
}

static int parse_unsigned_long(const char *value, unsigned long *out) {
    char *end = NULL;
    unsigned long parsed;
    if (value == NULL || value[0] == '\0' || out == NULL || value[0] == '-') {
        return 0;
    }
    errno = 0;
    parsed = strtoul(value, &end, 10);
    if (errno != 0 || end == value || *end != '\0') {
        return 0;
    }
    *out = parsed;
    return 1;
}

static int parse_cli_value_option(
    const char *argument,
    const char *value,
    authorization_cli *cli) {
    if (strcmp(argument, "--config") == 0) {
        cli->config_path = value;
        return 1;
    }
    if (strcmp(argument, "--listen") == 0) {
        cli->listen_spec = value;
        return 1;
    }
    if (strcmp(argument, "--max-requests") == 0) {
        return parse_unsigned_long(value, &cli->max_requests);
    }
    if (strcmp(argument, "--connection-timeout-ms") == 0) {
        return parse_unsigned_long(value, &cli->connection_timeout_ms) &&
            cli->connection_timeout_ms != 0UL &&
            cli->connection_timeout_ms <= AUTH_CONNECTION_TIMEOUT_MAX_MS;
    }
    if (strcmp(argument, "--max-connections") == 0) {
        return parse_unsigned_long(value, &cli->max_connections) &&
            cli->max_connections != 0UL &&
            cli->max_connections <= AUTH_MAX_CONNECTIONS_MAX;
    }
    return 0;
}

static int parse_cli(int argc, char **argv, authorization_cli *cli) {
    int skip_option_value = 0;
    memset(cli, 0, sizeof(*cli));
    cli->connection_timeout_ms = AUTH_CONNECTION_TIMEOUT_DEFAULT_MS;
    cli->max_connections = AUTH_MAX_CONNECTIONS_DEFAULT;
    for (int index = 1; index < argc; ++index) {
        if (skip_option_value) {
            skip_option_value = 0;
            continue;
        }
        if (strcmp(argv[index], "--check-config") == 0) {
            cli->check_config = 1;
        } else if (strcmp(argv[index], "--serve") == 0) {
            cli->serve = 1;
        } else if (index + 1 < argc &&
            parse_cli_value_option(argv[index], argv[index + 1], cli)) {
            skip_option_value = 1;
        } else {
            return 0;
        }
    }
    if ((cli->check_config != 0) == (cli->serve != 0) || cli->config_path == NULL) {
        return 0;
    }
    if (cli->serve && cli->listen_spec == NULL) {
        return 0;
    }
    return 1;
}

static size_t bounded_profile_text_size(const char *value, size_t maximum) {
    size_t size = 0U;
    if (value == NULL) {
        return 0U;
    }
    while (size < maximum && value[size] != '\0') {
        ++size;
    }
    return size;
}

static int validate_profile(const msconnector_http_authorization_profile *profile) {
    size_t connector_name_size;
    size_t integration_mode_size;
    if (profile == NULL || profile->connector_name == NULL ||
        profile->connector_name[0] == '\0' || profile->integration_mode == NULL ||
        profile->integration_mode[0] == '\0' || profile->transaction_profile == NULL ||
        profile->map_request == NULL) {
        return 0;
    }
    connector_name_size = bounded_profile_text_size(
        profile->connector_name, MSCONNECTOR_MAX_JSON_FIELD_LENGTH + 1U);
    integration_mode_size = bounded_profile_text_size(
        profile->integration_mode, MSCONNECTOR_MAX_JSON_FIELD_LENGTH + 1U);
    if (connector_name_size == 0U ||
        connector_name_size > MSCONNECTOR_MAX_JSON_FIELD_LENGTH ||
        integration_mode_size == 0U ||
        integration_mode_size > MSCONNECTOR_MAX_JSON_FIELD_LENGTH ||
        profile->original_uri_header_count > MSCONNECTOR_MAX_HEADER_COUNT ||
        (profile->original_uri_header_count > 0U &&
            profile->original_uri_headers == NULL)) {
        return 0;
    }
    if ((profile->handoff_response_companion == NULL) !=
        (profile->shutdown_response_companion == NULL)) {
        return 0;
    }
    if ((profile->terminal_response_marker_header == NULL) !=
        (profile->terminal_response_marker_value == NULL)) {
        return 0;
    }
    if (profile->terminal_response_marker_header != NULL &&
        (!valid_header_name(profile->terminal_response_marker_header) ||
         !valid_header_value(profile->terminal_response_marker_value))) {
        return 0;
    }
    for (size_t index = 0U; index < profile->original_uri_header_count; ++index) {
        const size_t header_name_size = bounded_profile_text_size(
            profile->original_uri_headers[index],
            MSCONNECTOR_MAX_HEADER_NAME_LENGTH + 1U);
        if (header_name_size == 0U ||
            header_name_size > MSCONNECTOR_MAX_HEADER_NAME_LENGTH) {
            return 0;
        }
    }
    return 1;
}

static int parse_listen_spec(
    const char *spec,
    char *host,
    size_t host_size,
    int *port) {
    const char *separator;
    size_t host_length;
    unsigned long parsed_port;
    if (spec == NULL || host == NULL || host_size == 0U || port == NULL) {
        return 0;
    }
    separator = strrchr(spec, ':');
    if (separator == NULL || separator == spec || separator[1] == '\0') {
        return 0;
    }
    host_length = (size_t)(separator - spec);
    if (host_length >= host_size ||
        !parse_unsigned_long(separator + 1, &parsed_port) ||
        parsed_port == 0UL || parsed_port > 65535UL) {
        return 0;
    }
    memcpy(host, spec, host_length);
    host[host_length] = '\0';
    if (strcmp(host, "localhost") == 0) {
        (void)snprintf(host, host_size, "%s", "127.0.0.1");
    }
    /* This endpoint has no authenticated transport.  Keep it loopback-only;
     * a wildcard bind would expose authorization decisions to the network. */
    if (strcmp(host, "127.0.0.1") != 0) {
        return 0;
    }
    *port = (int)parsed_port;
    return 1;
}

static void parsed_request_destroy(parsed_http_request *request) {
    if (request == NULL) {
        return;
    }
    free(request->headers);
    free(request->header_buffer);
    memset(request, 0, sizeof(*request));
}

static char *find_header_end(char *buffer, size_t size) {
    if (buffer == NULL || size < 4U) {
        return NULL;
    }
    for (size_t index = 0U; index + 3U < size; ++index) {
        if (buffer[index] == '\r' && buffer[index + 1U] == '\n' &&
            buffer[index + 2U] == '\r' && buffer[index + 3U] == '\n') {
            return buffer + index;
        }
    }
    return NULL;
}

/* Use an absolute monotonic deadline rather than an idle socket timeout so a
 * peer that drips bytes cannot retain the synchronous accept loop forever. */
static int connection_deadline_init(
    connection_deadline *deadline,
    unsigned long timeout_ms) {
    if (deadline == NULL || timeout_ms == 0UL ||
        timeout_ms > AUTH_CONNECTION_TIMEOUT_MAX_MS ||
        clock_gettime(CLOCK_MONOTONIC, &deadline->expires_at) != 0) {
        return 0;
    }
    deadline->expires_at.tv_sec += (time_t)(timeout_ms / 1000UL);
    deadline->expires_at.tv_nsec +=
        (long)((timeout_ms % 1000UL) * 1000000UL);
    if (deadline->expires_at.tv_nsec >= 1000000000L) {
        ++deadline->expires_at.tv_sec;
        deadline->expires_at.tv_nsec -= 1000000000L;
    }
    return 1;
}

static int connection_deadline_remaining_ms(const connection_deadline *deadline) {
    struct timespec now;
    time_t seconds;
    long nanoseconds;
    if (deadline == NULL || clock_gettime(CLOCK_MONOTONIC, &now) != 0) {
        return -1;
    }
    seconds = deadline->expires_at.tv_sec - now.tv_sec;
    nanoseconds = deadline->expires_at.tv_nsec - now.tv_nsec;
    if (nanoseconds < 0L) {
        --seconds;
        nanoseconds += 1000000000L;
    }
    if (seconds < 0 || (seconds == 0 && nanoseconds <= 0L)) {
        return 0;
    }
    if (seconds > (time_t)(INT_MAX / 1000)) {
        return INT_MAX;
    }
    return (int)(seconds * 1000 + (nanoseconds + 999999L) / 1000000L);
}

static int wait_for_socket(
    int socket_fd,
    short events,
    const connection_deadline *deadline) {
    struct pollfd descriptor;
    int timeout_ms;
    int result;
    if (socket_fd < 0) {
        return 0;
    }
    for (;;) {
        timeout_ms = connection_deadline_remaining_ms(deadline);
        if (timeout_ms <= 0) {
            return -1;
        }
        memset(&descriptor, 0, sizeof(descriptor));
        descriptor.fd = socket_fd;
        descriptor.events = events;
        result = poll(&descriptor, 1U, timeout_ms);
        if (result < 0 && errno == EINTR) {
            continue;
        }
        if (result == 0) {
            return -1;
        }
        if (result < 0) {
            return 0;
        }
        if ((descriptor.revents & events) != 0) {
            return 1;
        }
        if ((descriptor.revents & (POLLERR | POLLHUP | POLLNVAL)) != 0) {
            return 0;
        }
    }
}

static int recv_more(
    int socket_fd,
    void *buffer,
    size_t capacity,
    size_t *used,
    const connection_deadline *deadline) {
    ssize_t received;
    if (buffer == NULL || used == NULL || *used >= capacity) {
        return 0;
    }
    for (;;) {
        const int ready = wait_for_socket(socket_fd, POLLIN, deadline);
        if (ready != 1) {
            return ready;
        }
        do {
            received = recv(socket_fd, (char *)buffer + *used, capacity - *used, 0);
        } while (received < 0 && errno == EINTR);
        if (received < 0 && (errno == EAGAIN || errno == EWOULDBLOCK)) {
            continue;
        }
        if (received <= 0) {
            return 0;
        }
        *used += (size_t)received;
        return 1;
    }
}

static int http_token_character(unsigned char value);

static int parse_request_line(
    parsed_http_request *request,
    char *line,
    char *error,
    size_t error_len) {
    char *first_space;
    char *second_space;
    first_space = strchr(line, ' ');
    if (first_space == NULL) {
        (void)snprintf(error, error_len, "%s", "invalid HTTP request line");
        return 0;
    }
    *first_space = '\0';
    second_space = strchr(first_space + 1, ' ');
    if (second_space == NULL) {
        (void)snprintf(error, error_len, "%s", "invalid HTTP request line");
        return 0;
    }
    *second_space = '\0';
    request->method = line;
    request->uri = first_space + 1;
    request->http_version = second_space + 1;
    for (const char *cursor = request->method; *cursor != '\0'; ++cursor) {
        if (!http_token_character((unsigned char)*cursor)) {
            (void)snprintf(error, error_len, "%s", "invalid HTTP method");
            return 0;
        }
    }
    for (const char *cursor = request->uri; *cursor != '\0'; ++cursor) {
        unsigned char current = (unsigned char)*cursor;
        if (current <= 0x20U || current == 0x7fU) {
            (void)snprintf(error, error_len, "%s", "invalid HTTP request target");
            return 0;
        }
    }
    if (request->method[0] == '\0' || request->uri[0] != '/' ||
        strncmp(request->http_version, "HTTP/", 5U) != 0 ||
        strchr(request->http_version, ' ') != NULL ||
        strchr(request->http_version, '\t') != NULL) {
        (void)snprintf(error, error_len, "%s", "unsupported HTTP request line");
        return 0;
    }
    return 1;
}

static int http_token_character(unsigned char value) {
    if ((value >= (unsigned char)'a' && value <= (unsigned char)'z') ||
        (value >= (unsigned char)'A' && value <= (unsigned char)'Z') ||
        (value >= (unsigned char)'0' && value <= (unsigned char)'9')) {
        return 1;
    }
    return value == (unsigned char)'!' || value == (unsigned char)'#' ||
        value == (unsigned char)'$' || value == (unsigned char)'%' ||
        value == (unsigned char)'&' || value == (unsigned char)'\'' ||
        value == (unsigned char)'*' || value == (unsigned char)'+' ||
        value == (unsigned char)'-' || value == (unsigned char)'.' ||
        value == (unsigned char)'^' || value == (unsigned char)'_' ||
        value == (unsigned char)'`' || value == (unsigned char)'|' ||
        value == (unsigned char)'~';
}

static int valid_header_name(const char *name) {
    if (name == NULL || name[0] == '\0') {
        return 0;
    }
    for (size_t index = 0U; name[index] != '\0'; ++index) {
        if (!http_token_character((unsigned char)name[index])) {
            return 0;
        }
    }
    return 1;
}

static int valid_header_value(const char *value) {
    if (value == NULL) {
        return 0;
    }
    for (size_t index = 0U; value[index] != '\0'; ++index) {
        unsigned char current = (unsigned char)value[index];
        if ((current < 0x20U && current != (unsigned char)'\t') ||
            current == 0x7fU) {
            return 0;
        }
    }
    return 1;
}

static int parse_header_lines(
    parsed_http_request *request,
    const char *first_line_end,
    const char *header_end,
    size_t max_header_count,
    char *error,
    size_t error_len) {
    const char *cursor = request->header_buffer +
        (first_line_end - request->header_buffer) + 2;
    request->headers = calloc(max_header_count, sizeof(*request->headers));
    if (request->headers == NULL) {
        (void)snprintf(error, error_len, "%s", "header allocation failed");
        return 0;
    }
    while (cursor < header_end) {
        char *line_end = strstr(cursor, "\r\n");
        char *colon;
        const char *value;
        char *value_end;
        if (line_end == NULL || line_end > header_end) {
            (void)snprintf(error, error_len, "%s", "invalid HTTP header line");
            return 0;
        }
        if (line_end == cursor) {
            break;
        }
        if (request->header_count >= max_header_count) {
            (void)snprintf(error, error_len, "%s", "too many HTTP headers");
            return 0;
        }
        *line_end = '\0';
        colon = strchr(cursor, ':');
        if (colon == NULL || colon == cursor) {
            (void)snprintf(error, error_len, "%s", "invalid HTTP header");
            return 0;
        }
        *colon = '\0';
        value = colon + 1;
        while (*value == ' ' || *value == '\t') {
            ++value;
        }
        value_end = line_end;
        while (value_end > value &&
            (value_end[-1] == ' ' || value_end[-1] == '\t')) {
            *--value_end = '\0';
        }
        if (!valid_header_name(cursor) || !valid_header_value(value)) {
            (void)snprintf(error, error_len, "%s", "invalid HTTP header syntax");
            return 0;
        }
        request->headers[request->header_count].name = cursor;
        request->headers[request->header_count].name_size = strlen(cursor);
        request->headers[request->header_count].value = value;
        request->headers[request->header_count].value_size = strlen(value);
        ++request->header_count;
        cursor = line_end + 2;
    }
    return 1;
}

static int header_value_equals(
    const msconnector_header *header,
    const char *expected) {
    size_t expected_size = strlen(expected);
    return header != NULL && header->value != NULL &&
        header->value_size == expected_size &&
        strncasecmp(header->value, expected, expected_size) == 0;
}

static int transfer_encoding_supported(const parsed_http_request *request) {
    size_t count = msconnector_headers_count_name(
        request->headers, request->header_count, "transfer-encoding");
    const msconnector_header *header = msconnector_headers_find_first(
        request->headers, request->header_count, "transfer-encoding");
    return count == 0U || (count == 1U && header_value_equals(header, "identity"));
}

/* Keep only the body bytes already borrowed from the bounded header buffer.
 * Remaining entity bytes are read incrementally into a fixed working buffer. */
static int prepare_request_body(
    parsed_http_request *request, const char *body_start,
    size_t buffered_body_size, char *error, size_t error_len) {
    size_t content_length = 0U;
    if (!transfer_encoding_supported(request)) {
        (void)snprintf(error, error_len, "%s", "chunked request bodies are unsupported");
        return 0;
    }
    if (msconnector_headers_find_first(request->headers, request->header_count,
            "content-length") != NULL &&
        msconnector_headers_parse_content_length(request->headers,
            request->header_count, &content_length) != 1) {
        (void)snprintf(error, error_len, "%s", "invalid content-length header");
        return 0;
    }
    request->content_length = content_length;
    request->body = (const uint8_t *)body_start;
    request->body_size = buffered_body_size < content_length
        ? buffered_body_size : content_length;
    return 1;
}

static int read_http_request(
    const authorization_connection *connection,
    const authorization_request_limits *limits,
    parsed_http_request *request,
    char *error,
    size_t error_len) {
    size_t header_limit;
    size_t header_capacity;
    size_t used = 0U;
    const char *header_end;
    char *first_line_end;
    const char *body_start;
    size_t buffered_body_size;
    if (limits == NULL) {
        (void)snprintf(error, error_len, "%s", "request limits are unavailable");
        return 0;
    }
    header_limit = limits->total_header_limit;
    if (header_limit > SIZE_MAX - AUTH_REQUEST_LINE_OVERHEAD - 1U) {
        (void)snprintf(error, error_len, "%s", "configured header limit is too large");
        return 0;
    }
    header_capacity = header_limit + AUTH_REQUEST_LINE_OVERHEAD;
    request->header_buffer = malloc(header_capacity + 1U);
    if (request->header_buffer == NULL) {
        (void)snprintf(error, error_len, "%s", "request allocation failed");
        return 0;
    }
    header_end = NULL;
    while (header_end == NULL) {
        const int received = recv_more(
            connection->socket_fd, request->header_buffer, header_capacity, &used,
            connection->read_deadline);
        if (received != 1) {
            (void)snprintf(error, error_len, "%s",
                received < 0 ? "HTTP request headers timed out" :
                "incomplete HTTP request headers");
            return 0;
        }
        header_end = find_header_end(request->header_buffer, used);
        if (header_end == NULL && used == header_capacity) {
            (void)snprintf(error, error_len, "%s", "HTTP headers exceed configured limit");
            return 0;
        }
    }
    request->header_buffer[used] = '\0';
    request->header_buffer_size = used;
    first_line_end = strstr(request->header_buffer, "\r\n");
    if (first_line_end == NULL || first_line_end >= header_end) {
        (void)snprintf(error, error_len, "%s", "missing HTTP request line");
        return 0;
    }
    *first_line_end = '\0';
    if (!parse_request_line(request, request->header_buffer, error, error_len) ||
        !parse_header_lines(request, first_line_end, header_end,
            limits->header_count_limit, error, error_len)) {
        return 0;
    }
    body_start = header_end + 4;
    buffered_body_size = used - (size_t)(body_start - request->header_buffer);
    if (!prepare_request_body(request, body_start, buffered_body_size,
            error, error_len)) {
        return 0;
    }
    if (inet_ntop(AF_INET, &connection->peer->sin_addr, request->client_address,
            sizeof(request->client_address)) == NULL ||
        inet_ntop(AF_INET, &connection->local->sin_addr, request->server_address,
            sizeof(request->server_address)) == NULL) {
        (void)snprintf(error, error_len, "%s", "endpoint address conversion failed");
        return 0;
    }
    request->client_port = (int)ntohs(connection->peer->sin_port);
    request->server_port = (int)ntohs(connection->local->sin_port);
    return 1;
}

static int copy_slice(
    const char *value,
    size_t value_size,
    char *destination,
    size_t destination_size) {
    if (value == NULL || destination == NULL || destination_size == 0U ||
        value_size >= destination_size) {
        return 0;
    }
    memcpy(destination, value, value_size);
    destination[value_size] = '\0';
    return 1;
}

static const char *request_uri(
    parsed_http_request *request,
    const msconnector_http_authorization_profile *profile) {
    for (size_t index = 0U; index < profile->original_uri_header_count; ++index) {
        const msconnector_header *header = msconnector_headers_find_first(
            request->headers, request->header_count,
            profile->original_uri_headers[index]);
        if (header == NULL) {
            continue;
        }
        /* B13: a present authoritative field must never become a fallback
         * to a different header or to the authorization endpoint itself. */
        if (header->value == NULL || header->value_size == 0U ||
            header->value_size > MSCONNECTOR_MAX_HEADER_VALUE_LENGTH ||
            header->value[0] != '/' ||
            memchr(header->value, '\0', header->value_size) != NULL ||
            !copy_slice(header->value, header->value_size,
                request->uri_override, sizeof(request->uri_override))) {
            return NULL;
        }
        return request->uri_override;
    }
    return request->uri;
}

static int security_header_duplicates_are_rejected(
    const parsed_http_request *request,
    const msconnector_http_authorization_profile *profile,
    char *error,
    size_t error_len) {
    if (request == NULL || profile == NULL || error == NULL || error_len == 0U) {
        return 0;
    }
    if (msconnector_headers_count_name(
            request->headers, request->header_count, "host") > 1U) {
        (void)snprintf(error, error_len, "%s", "duplicate Host header");
        return 0;
    }
    for (size_t index = 0U; index < profile->original_uri_header_count; ++index) {
        const char *name = profile->original_uri_headers[index];
        if (msconnector_headers_count_name(
                request->headers, request->header_count, name) > 1U) {
            (void)snprintf(error, error_len,
                "duplicate security-sensitive header: %s", name);
            return 0;
        }
    }
    return 1;
}

static int request_hostname(
    parsed_http_request *request,
    char *error,
    size_t error_len) {
    const msconnector_header *host = msconnector_headers_find_first(
        request->headers, request->header_count, "host");
    if (host != NULL && host->value_size > 0U &&
        copy_slice(host->value, host->value_size,
            request->hostname, sizeof(request->hostname))) {
        return 1;
    }
    if (error != NULL && error_len > 0U) {
        (void)snprintf(error, error_len, "%s", "missing or invalid Host header");
    }
    return 0;
}

static int send_all(
    int socket_fd,
    const char *data,
    size_t size,
    const connection_deadline *deadline) {
    size_t sent = 0U;
    while (sent < size) {
        ssize_t result;
        const int ready = wait_for_socket(socket_fd, POLLOUT, deadline);
        if (ready != 1) {
            return 0;
        }
        do {
#ifdef MSG_NOSIGNAL
            result = send(socket_fd, data + sent, size - sent, MSG_NOSIGNAL);
#else
            result = send(socket_fd, data + sent, size - sent, 0);
#endif
        } while (result < 0 && errno == EINTR);
        if (result < 0 && (errno == EAGAIN || errno == EWOULDBLOCK)) {
            continue;
        }
        if (result <= 0) {
            return 0;
        }
        sent += (size_t)result;
    }
    return 1;
}

static int optional_header_pair_is_valid(const char *name, const char *value);

static int write_response_handle_header(
    char *output,
    size_t output_size,
    const char *response_handle) {
    if (response_handle == NULL) {
        output[0] = '\0';
        return 1;
    }
    if (strlen(response_handle) !=
        MSCONNECTOR_RUNTIME_RESPONSE_COMPANION_HANDLE_SIZE - 1U) {
        return 0;
    }
    for (size_t index = 0U;
         index < MSCONNECTOR_RUNTIME_RESPONSE_COMPANION_HANDLE_SIZE - 1U;
         ++index) {
        const unsigned char character = (unsigned char)response_handle[index];
        if (!((character >= (unsigned char)'0' && character <= (unsigned char)'9') ||
              (character >= (unsigned char)'a' && character <= (unsigned char)'f'))) {
            return 0;
        }
    }
    return snprintf(output, output_size,
        "x-msconnector-response-handle: %s\r\n", response_handle) >= 0 &&
        strlen(output) < output_size;
}

/* A redirect target crosses from a native decision into the HTTP response
 * serializer.  Retain a bounded response-owned copy and reject control bytes,
 * empty values, overlong values, and leading/trailing whitespace rather than
 * truncating or emitting an ambiguous Location field. */
static int copy_redirect_location(
    char *destination,
    size_t destination_size,
    const char *source) {
    if (destination == NULL || destination_size < 2U || source == NULL) {
        return 0;
    }
    for (size_t index = 0U; index < destination_size - 1U; ++index) {
        const unsigned char character = (unsigned char)source[index];

        if (character == '\0') {
            if (index == 0U || destination[0] == ' ' ||
                destination[index - 1U] == ' ') {
                destination[0] = '\0';
                return 0;
            }
            destination[index] = '\0';
            return 1;
        }
        if (character < 0x20U || character == 0x7fU) {
            destination[0] = '\0';
            return 0;
        }
        destination[index] = (char)character;
    }
    destination[0] = '\0';
    return 0;
}

static int send_response(
    int socket_fd,
    const authorization_response_state *response_state,
    const char *terminal_marker_header,
    const char *terminal_marker_value,
    unsigned long timeout_ms) {
    char response[AUTH_RESPONSE_SIZE];
    char companion_header[MSCONNECTOR_RUNTIME_RESPONSE_COMPANION_HANDLE_SIZE + 48U];
    char location_header[AUTH_REDIRECT_LOCATION_SIZE + 16U];
    char copied_location[AUTH_REDIRECT_LOCATION_SIZE];
    char terminal_marker[AUTH_RESPONSE_SIZE / 4U];
    connection_deadline deadline;
    int status;
    const char *response_handle;
    const char *redirect_location;
    const char *decision_name;
    const char *reason;
    const char *body;
    int written;

    if (response_state == NULL) {
        return 0;
    }
    status = response_state->status;
    response_handle = response_state->response_handle;
    redirect_location = response_state->redirect_location;
    decision_name = response_state->decision_name;
    reason = msconnector_http_status_reason_phrase(status);
    body = status >= 400 ? "request denied\n" : "request allowed\n";
    if (!msconnector_http_status_is_valid(status)) {
        status = 500;
        reason = msconnector_http_status_reason_phrase(status);
        body = "authorization service error\n";
        decision_name = "runtime_error";
    }
    location_header[0] = '\0';
    if (status >= 300 && status < 400) {
        if (!copy_redirect_location(copied_location, sizeof(copied_location),
                redirect_location)) {
            status = 500;
            reason = msconnector_http_status_reason_phrase(status);
            body = "authorization service error\n";
            decision_name = "runtime_error";
        } else if (snprintf(location_header, sizeof(location_header),
                "location: %s\r\n", copied_location) < 0 ||
            strlen(location_header) >= sizeof(location_header)) {
            return 0;
        }
    } else if (redirect_location != NULL) {
        status = 500;
        reason = msconnector_http_status_reason_phrase(status);
        body = "authorization service error\n";
        decision_name = "runtime_error";
    }
    companion_header[0] = '\0';
    terminal_marker[0] = '\0';
    if (!write_response_handle_header(companion_header, sizeof(companion_header),
            response_handle)) {
        return 0;
    }
    if (!optional_header_pair_is_valid(terminal_marker_header,
            terminal_marker_value)) {
        return 0;
    }
    if (terminal_marker_header != NULL &&
        (snprintf(terminal_marker, sizeof(terminal_marker), "%s: %s\r\n",
             terminal_marker_header, terminal_marker_value) < 0 ||
         strlen(terminal_marker) >= sizeof(terminal_marker))) {
        return 0;
    }
    written = snprintf(response, sizeof(response),
        "HTTP/1.1 %d %s\r\n"
        "content-type: text/plain\r\n"
        "content-length: %zu\r\n"
        "connection: close\r\n"
        "x-msconnector-decision: %s\r\n"
        "%s"
        "%s"
        "%s"
        "\r\n%s",
        status,
        reason,
        strlen(body),
        decision_name == NULL ? "error" : decision_name,
        companion_header,
        location_header,
        terminal_marker,
        body);
    if (written < 0 || (size_t)written >= sizeof(response)) {
        return 0;
    }
    return connection_deadline_init(&deadline, timeout_ms) &&
        send_all(socket_fd, response, (size_t)written, &deadline);
}

static int optional_header_pair_is_valid(const char *name, const char *value)
{
    if ((name == NULL) != (value == NULL)) {
        return 0;
    }
    if (name == NULL) {
        return 1;
    }
    return valid_header_name(name) && valid_header_value(value);
}

static int error_status_from_message(const char *message) {
    if (message != NULL && strstr(message, "timed out") != NULL) {
        return 408;
    }
    if (message != NULL &&
        (strstr(message, "header") != NULL || strstr(message, "Header") != NULL) &&
        (strstr(message, "limit") != NULL ||
         strstr(message, "exceed") != NULL ||
         strstr(message, "too many") != NULL)) {
        return 431;
    }
    if (message != NULL && strstr(message, "chunked") != NULL) {
        return 501;
    }
    return 400;
}

static void authorization_response_set_runtime_error(
    const authorization_service *service,
    const msconnector_error *common_error,
    authorization_response_state *response) {
    const msconnector_error_code code = common_error == NULL ||
        common_error->code == MSCONNECTOR_ERROR_NONE ?
        MSCONNECTOR_ERROR_INTERNAL : common_error->code;

    if (response == NULL) {
        return;
    }

    /* `use_error_log` is deliberately limited to classification and the
     * fixed source component.  Request IDs, header values, and body data must
     * not reach this diagnostic channel. */
    if (service != NULL && service->runtime != NULL && service->profile != NULL &&
        msconnector_runtime_error_log_enabled(service->runtime)) {
        (void)fprintf(stderr,
            "connector=%s integration_mode=%s runtime_error=%s source=%s\n",
            service->profile->connector_name,
            service->profile->integration_mode,
            msconnector_error_code_name(code),
            common_error != NULL && common_error->source != NULL ?
                common_error->source : "runtime");
    }
    response->status = service != NULL && service->runtime != NULL ?
        msconnector_runtime_error_http_status(service->runtime, code) : 500;
    response->decision_name = "runtime_error";
    response->response_handle = NULL;
    response->redirect_location = NULL;
    msconnector_secure_zero(response->copied_redirect_location,
        sizeof(response->copied_redirect_location));
    response->success = 0;
}

static void authorization_response_set_decision(
    const authorization_service *service,
    const msconnector_decision *decision,
    authorization_response_state *response) {
    const msconnector_decision_action action =
        msconnector_decision_action_from_decision(decision);

    response->redirect_location = NULL;
    msconnector_secure_zero(response->copied_redirect_location,
        sizeof(response->copied_redirect_location));
    response->decision_name = msconnector_decision_action_name(action);
    if (action == MSCONNECTOR_DECISION_ACTION_ALLOW ||
        action == MSCONNECTOR_DECISION_ACTION_LOG_ONLY) {
        response->status = 200;
    } else {
        response->status = msconnector_decision_http_status(decision);
        if (!msconnector_http_status_is_valid(response->status)) {
            response->status = action == MSCONNECTOR_DECISION_ACTION_ERROR ? 500 : 403;
        }
    }
    if (action == MSCONNECTOR_DECISION_ACTION_REDIRECT) {
        if (!copy_redirect_location(response->copied_redirect_location,
                sizeof(response->copied_redirect_location), decision->redirect_url)) {
            authorization_response_set_runtime_error(service, NULL, response);
            return;
        }
        response->redirect_location = response->copied_redirect_location;
    }
    response->success = 1;
}

static int authorization_stream_request_body(
    authorization_service *service, const authorization_connection *connection,
    const parsed_http_request *parsed, msconnector_runtime_transaction *transaction,
    msconnector_decision *decision, msconnector_error *error, int *lock_held) {
    unsigned char scratch[16384];
    size_t remaining = parsed->content_length - parsed->body_size;
    if (msconnector_runtime_request_body_mode(service->runtime) == MSCONNECTOR_BODY_MODE_NONE) {
        if (parsed->content_length == 0U) return 1; /* begin already closed P2 */
        msconnector_error_set(error, MSCONNECTOR_ERROR_UNSUPPORTED_PHASE,
            "request body is disabled", "http_authorization_service");
        return 0;
    }
    if (msconnector_runtime_transaction_append_request_body_chunk(transaction,
            parsed->body, parsed->body_size, error) != 1) return 0;
    while (remaining > 0U) {
        size_t received_size = 0U;
        const size_t capacity = remaining < sizeof(scratch) ? remaining : sizeof(scratch);
        int received;
        /* A slow socket must not monopolize the shared engine/service lock. */
        if (pthread_mutex_unlock(&service->runtime_lock) != 0) {
            msconnector_error_set(error, MSCONNECTOR_ERROR_INTERNAL,
                "runtime lock release failed", "http_authorization_service");
            return 0;
        }
        *lock_held = 0;
        received = recv_more(connection->socket_fd, scratch, capacity, &received_size,
            connection->read_deadline);
        if (pthread_mutex_lock(&service->runtime_lock) != 0) {
            msconnector_error_set(error, MSCONNECTOR_ERROR_INTERNAL,
                "runtime lock acquisition failed", "http_authorization_service");
            return 0;
        }
        *lock_held = 1;
        if (received != 1) {
            msconnector_error terminal_error;
            msconnector_error_init(&terminal_error);
            (void)msconnector_runtime_transaction_fail(transaction,
                MSCONNECTOR_TRANSACTION_ERROR_PROTOCOL, &terminal_error);
            msconnector_error_set(error, MSCONNECTOR_ERROR_HOST_API_FAILURE,
                received < 0 ? "request body read timed out" : "incomplete request body",
                "http_authorization_service");
            return 0;
        }
        if (msconnector_runtime_transaction_append_request_body_chunk(transaction,
                scratch, received_size, error) != 1) return 0;
        remaining -= received_size;
    }
    return msconnector_runtime_transaction_finish_request_body(transaction, decision, error);
}

static void authorization_response_set_stream_error(
    const authorization_service *service, const msconnector_error *common_error,
    authorization_response_state *response) {
    authorization_response_set_runtime_error(service, common_error, response);
    if (common_error->code == MSCONNECTOR_ERROR_HOST_API_FAILURE &&
        common_error->source != NULL &&
        strcmp(common_error->source, "http_authorization_service") == 0) {
        response->status = error_status_from_message(common_error->message);
    }
}

/* Mapping diagnostics borrow a bounded caller-owned output buffer. */
typedef struct authorization_mapping_error {
    char *data;
    size_t capacity;
} authorization_mapping_error;

static void authorization_process_runtime_request(
    authorization_service *service,
    const authorization_connection *connection,
    const parsed_http_request *parsed,
    int *lock_held,
    const msconnector_generic_request_source *source,
    const authorization_mapping_error *mapping_error,
    authorization_response_state *response) {
    msconnector_request request;
    msconnector_runtime_transaction *transaction = NULL;
    msconnector_decision decision;
    msconnector_error common_error;
    char response_handle[MSCONNECTOR_RUNTIME_RESPONSE_COMPANION_HANDLE_SIZE];
    int response_companion_owns_transaction = 0;
    memset(&request, 0, sizeof(request));
    msconnector_error_init(&common_error);
    msconnector_decision_set_allow(&decision);
    msconnector_secure_zero(response_handle, sizeof(response_handle));
    response->response_handle = NULL;
    if (!service->profile->map_request(source, &service->request_limits.mapper_contract,
            &request, mapping_error->data, mapping_error->capacity)) {
        response->status = 400;
        response->decision_name = "mapping_error";
        response->success = 0;
    } else if (msconnector_runtime_transaction_begin_request_stream(service->runtime, &request, NULL,
            &transaction, &decision, &common_error) != 1) {
        authorization_response_set_runtime_error(service, &common_error, response);
    } else {
        if (!msconnector_decision_action_is_disruptive(
                msconnector_decision_action_from_decision(&decision)) &&
            authorization_stream_request_body(service, connection, parsed,
                transaction, &decision, &common_error, lock_held) != 1) {
            authorization_response_set_stream_error(service, &common_error, response);
        } else {
            authorization_response_set_decision(service, &decision, response);
        }
        if (response->success && service->profile->handoff_response_companion != NULL &&
            (msconnector_decision_action_from_decision(&decision) ==
                MSCONNECTOR_DECISION_ACTION_ALLOW ||
             msconnector_decision_action_from_decision(&decision) ==
                MSCONNECTOR_DECISION_ACTION_LOG_ONLY)) {
            if (service->profile->handoff_response_companion(service->runtime,
                    transaction, service->profile->response_companion_userdata,
                    response_handle, &common_error) != 1) {
                authorization_response_set_runtime_error(service, &common_error, response);
            } else {
                /* The companion owns this live Common/native transaction until
                 * P3/P4 EOS or TTL cleanup. It is not safe for the
                 * request-only authorization service to finish or destroy it. */
                response_companion_owns_transaction = 1;
                memmove(response->copied_response_handle, response_handle,
                    sizeof(response->copied_response_handle));
                response->response_handle = response->copied_response_handle;
            }
        }
    }
    if (!response_companion_owns_transaction && transaction != NULL) {
        msconnector_error finish_error;
        msconnector_error_init(&finish_error);
        if (msconnector_runtime_transaction_finish(transaction, &finish_error) != 1 &&
            response->success) {
            authorization_response_set_runtime_error(service, &finish_error, response);
        }
    }
    if (!response_companion_owns_transaction) {
        response->terminal_response_marker =
            service->profile->terminal_response_marker_header != NULL &&
            service->profile->terminal_response_marker_value != NULL;
        msconnector_runtime_transaction_destroy(&transaction);
    }
    msconnector_secure_zero(response_handle, sizeof(response_handle));
}

static int handle_authorization_request(
    const authorization_connection *connection,
    authorization_service *service) {
    parsed_http_request parsed;
    msconnector_generic_request_source source;
    authorization_response_state response;
    char error[AUTH_ERROR_SIZE];

    if (connection == NULL || service == NULL || service->runtime == NULL ||
        service->profile == NULL) {
        return 0;
    }
    memset(&parsed, 0, sizeof(parsed));
    memset(&source, 0, sizeof(source));
    memset(&response, 0, sizeof(response));
    error[0] = '\0';
    if (!read_http_request(connection, &service->request_limits,
            &parsed, error, sizeof(error))) {
        response.status = error_status_from_message(error);
        response.decision_name = "invalid_request";
        (void)send_response(
            connection->socket_fd, &response, NULL, NULL,
            service->connection_timeout_ms);
        parsed_request_destroy(&parsed);
        return 0;
    }
    if (!security_header_duplicates_are_rejected(
            &parsed, service->profile, error, sizeof(error))) {
        response.status = 400;
        response.decision_name = "invalid_request";
        (void)send_response(
            connection->socket_fd, &response, NULL, NULL,
            service->connection_timeout_ms);
        parsed_request_destroy(&parsed);
        return 0;
    }
    if (!request_hostname(&parsed, error, sizeof(error))) {
        response.status = 400;
        response.decision_name = "invalid_request";
        (void)send_response(
            connection->socket_fd, &response, NULL, NULL,
            service->connection_timeout_ms);
        parsed_request_destroy(&parsed);
        return 0;
    }
    source.method = parsed.method;
    source.uri = request_uri(&parsed, service->profile);
    if (source.uri == NULL) {
        response.status = 400;
        response.decision_name = "invalid_request";
        (void)send_response(
            connection->socket_fd, &response, NULL, NULL,
            service->connection_timeout_ms);
        parsed_request_destroy(&parsed);
        return 0;
    }
    source.http_version = parsed.http_version;
    source.hostname = parsed.hostname;
    source.client.address = parsed.client_address;
    source.client.port = parsed.client_port;
    source.server.address = parsed.server_address;
    source.server.port = parsed.server_port;
    source.headers = parsed.headers;
    source.header_count = parsed.header_count;
    source.body.data = NULL;
    source.body.size = 0U;
    if (pthread_mutex_lock(&service->runtime_lock) != 0) {
        response.status = 500;
        response.decision_name = "runtime_error";
        (void)send_response(connection->socket_fd, &response, NULL, NULL,
            service->connection_timeout_ms);
        parsed_request_destroy(&parsed);
        return 0;
    }
    int runtime_lock_held = 1;
    const authorization_mapping_error mapping_error = {error, sizeof(error)};
    authorization_process_runtime_request(service, connection, &parsed,
        &runtime_lock_held, &source, &mapping_error, &response);
    if (runtime_lock_held && pthread_mutex_unlock(&service->runtime_lock) != 0) {
        parsed_request_destroy(&parsed);
        return 0;
    }
    if (!send_response(
            connection->socket_fd, &response,
            response.terminal_response_marker ?
                service->profile->terminal_response_marker_header : NULL,
            response.terminal_response_marker ?
                service->profile->terminal_response_marker_value : NULL,
            service->connection_timeout_ms)) {
        if (response.response_handle != NULL &&
            service->profile->revoke_response_companion != NULL) {
            msconnector_error revoke_error;
            msconnector_error_init(&revoke_error);
            (void)service->profile->revoke_response_companion(
                service->profile->response_companion_userdata,
                response.response_handle, &revoke_error);
        }
        response.success = 0;
    }
    parsed_request_destroy(&parsed);
    return response.success;
}

static int create_listener(
    const char *listen_spec,
    int *listener,
    struct sockaddr_in *local,
    char *error,
    size_t error_len) {
    char host[AUTH_LISTEN_HOST_SIZE];
    int port;
    int enabled = 1;
    int socket_fd;
    if (!parse_listen_spec(listen_spec, host, sizeof(host), &port)) {
        (void)snprintf(error, error_len, "%s", "invalid --listen value");
        return 0;
    }
    memset(local, 0, sizeof(*local));
    local->sin_family = AF_INET;
    local->sin_port = htons((uint16_t)port);
    if (inet_pton(AF_INET, host, &local->sin_addr) != 1) {
        (void)snprintf(error, error_len, "%s", "invalid listen address");
        return 0;
    }
    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd < 0) {
        (void)snprintf(error, error_len, "socket failed: %s", strerror(errno));
        return 0;
    }
    if (setsockopt(socket_fd, SOL_SOCKET, SO_REUSEADDR, &enabled, sizeof(enabled)) != 0 ||
        bind(socket_fd, (const struct sockaddr *)local, sizeof(*local)) != 0 ||
        listen(socket_fd, 128) != 0) {
        (void)snprintf(error, error_len, "listen setup failed: %s", strerror(errno));
        (void)close(socket_fd);
        return 0;
    }
    *listener = socket_fd;
    return 1;
}

static int configure_client_socket(int socket_fd) {
    int flags;
    if (socket_fd < 0) {
        return 0;
    }
#if !defined(MSG_NOSIGNAL)
#if defined(SO_NOSIGPIPE)
    {
        int enabled = 1;
        if (setsockopt(socket_fd, SOL_SOCKET, SO_NOSIGPIPE,
                &enabled, sizeof(enabled)) != 0) {
            return 0;
        }
    }
#else
    /* Never expose send(..., 0) to an unprotected client socket. */
    errno = ENOTSUP;
    return 0;
#endif
#endif
    flags = fcntl(socket_fd, F_GETFL, 0);
    return flags >= 0 && fcntl(socket_fd, F_SETFL, flags | O_NONBLOCK) == 0;
}

static int authorization_copy_profile(
    authorization_service *service,
    const msconnector_http_authorization_profile *profile) {
    size_t connector_name_size;
    size_t integration_mode_size;

    if (service == NULL || !validate_profile(profile)) {
        return 0;
    }
    connector_name_size = bounded_profile_text_size(
        profile->connector_name, sizeof(service->copied_connector_name));
    integration_mode_size = bounded_profile_text_size(
        profile->integration_mode, sizeof(service->copied_integration_mode));
    memcpy(service->copied_connector_name, profile->connector_name,
        connector_name_size + 1U);
    memcpy(service->copied_integration_mode, profile->integration_mode,
        integration_mode_size + 1U);
    service->profile_copy = *profile;
    service->profile_copy.connector_name = service->copied_connector_name;
    service->profile_copy.integration_mode = service->copied_integration_mode;
    service->profile_copy.original_uri_headers = NULL;
    for (size_t index = 0U; index < profile->original_uri_header_count; ++index) {
        const size_t header_name_size = bounded_profile_text_size(
            profile->original_uri_headers[index],
            sizeof(service->copied_original_uri_header_names[index]));
        memcpy(service->copied_original_uri_header_names[index],
            profile->original_uri_headers[index], header_name_size + 1U);
        service->copied_original_uri_headers[index] =
            service->copied_original_uri_header_names[index];
    }
    if (profile->original_uri_header_count > 0U) {
        service->profile_copy.original_uri_headers =
            service->copied_original_uri_headers;
    }
    service->profile = &service->profile_copy;
    return 1;
}

static int authorization_service_init(
    authorization_service *service,
    msconnector_runtime *runtime,
    const msconnector_http_authorization_profile *profile,
    const authorization_cli *cli) {
    if (service == NULL || runtime == NULL || profile == NULL || cli == NULL ||
        cli->max_connections == 0UL ||
        cli->max_connections > AUTH_MAX_CONNECTIONS_MAX) {
        return 0;
    }
    memset(service, 0, sizeof(*service));
    service->runtime = runtime;
    /* Workers can outlive the entry-point stack during bounded shutdown.
     * Keep a bounded, fully-owned profile copy with the heap-owned service.
     * Mapping callbacks are code pointers; all textual and header data is
     * copied before a worker can outlive the entry-point stack. */
    if (!authorization_copy_profile(service, profile)) {
        return 0;
    }
    service->connection_timeout_ms = cli->connection_timeout_ms;
    service->max_connections = cli->max_connections;
    msconnector_runtime_request_contract(runtime, &service->request_limits.mapper_contract);
    service->request_limits.total_header_limit =
        msconnector_runtime_total_header_limit(runtime);
    service->request_limits.header_count_limit =
        msconnector_runtime_header_count_limit(runtime);
    if (pthread_mutex_init(&service->runtime_lock, NULL) != 0) {
        return 0;
    }
    if (pthread_mutex_init(&service->worker_lock, NULL) != 0) {
        (void)pthread_mutex_destroy(&service->runtime_lock);
        return 0;
    }
    if (pthread_cond_init(&service->workers_idle, NULL) != 0) {
        (void)pthread_mutex_destroy(&service->worker_lock);
        (void)pthread_mutex_destroy(&service->runtime_lock);
        return 0;
    }
    return 1;
}

static void authorization_service_destroy(authorization_service *service) {
    if (service == NULL) {
        return;
    }
    (void)pthread_cond_destroy(&service->workers_idle);
    (void)pthread_mutex_destroy(&service->worker_lock);
    (void)pthread_mutex_destroy(&service->runtime_lock);
    memset(service, 0, sizeof(*service));
}

static int authorization_service_release(authorization_service *service) {
    if (service == NULL) {
        return 1;
    }
    msconnector_runtime_destroy(&service->runtime);
    authorization_service_destroy(service);
    free(service);
    return 1;
}

static void authorization_worker_release(authorization_worker *worker) {
    authorization_service *service;
    int release_service = 0;
    if (worker == NULL) {
        return;
    }
    service = worker->service;
    if (service != NULL && pthread_mutex_lock(&service->worker_lock) == 0) {
        authorization_worker **current = &service->workers;
        while (*current != NULL && *current != worker) {
            current = &(*current)->next;
        }
        if (*current == worker) {
            *current = worker->next;
            if (service->active_workers > 0UL) {
                --service->active_workers;
            }
            if (service->active_workers == 0UL && service->deferred_cleanup &&
                service->response_companion_quiesced && !service->release_claimed) {
                service->deferred_cleanup = 0;
                service->release_claimed = 1;
                release_service = 1;
            }
            (void)pthread_cond_broadcast(&service->workers_idle);
        }
        (void)pthread_mutex_unlock(&service->worker_lock);
    }
    if (worker->socket_fd >= 0) {
        (void)close(worker->socket_fd);
    }
    free(worker);
    if (release_service) {
        (void)authorization_service_release(service);
    }
}

static void *authorization_worker_main(void *argument) {
    authorization_worker *worker = argument;
    authorization_connection connection;
    int request_result;
    if (worker == NULL) {
        return NULL;
    }
    connection.socket_fd = worker->socket_fd;
    connection.peer = &worker->peer;
    connection.local = &worker->local;
    connection.read_deadline = &worker->read_deadline;
    request_result = handle_authorization_request(&connection, worker->service);
    if (!request_result) {
        (void)fprintf(stderr, "%s authorization request terminated without "
            "a response\n", worker->service->profile->connector_name);
    }
    authorization_worker_release(worker);
    return NULL;
}

static int authorization_start_worker(
    authorization_service *service,
    int socket_fd,
    const struct sockaddr_in *peer,
    const struct sockaddr_in *local,
    const connection_deadline *read_deadline) {
    authorization_worker *worker;
    pthread_attr_t attributes;
    pthread_t thread;
    sigset_t previous_signal_mask;
    int worker_created = 0;
    int result;
    if (service == NULL || socket_fd < 0 || peer == NULL || local == NULL ||
        read_deadline == NULL) {
        if (socket_fd >= 0) {
            (void)close(socket_fd);
        }
        return -1;
    }
    worker = calloc(1U, sizeof(*worker));
    if (worker == NULL) {
        (void)close(socket_fd);
        return -1;
    }
    worker->service = service;
    worker->socket_fd = socket_fd;
    worker->peer = *peer;
    worker->local = *local;
    worker->read_deadline = *read_deadline;
    /* Signals are blocked while creating the worker so it inherits a mask
     * that excludes SIGTERM/SIGINT.  The handler therefore has one owner:
     * the serving thread.  This also prevents the signal handler and a
     * worker read of authorization_stop from racing. */
    if (!authorization_block_termination_signals(&previous_signal_mask)) {
        (void)close(socket_fd);
        free(worker);
        return -1;
    }
    if (pthread_mutex_lock(&service->worker_lock) != 0) {
        (void)authorization_restore_signal_mask(&previous_signal_mask);
        (void)close(socket_fd);
        free(worker);
        return -1;
    }
    if (service->active_workers >= service->max_connections) {
        (void)pthread_mutex_unlock(&service->worker_lock);
        (void)authorization_restore_signal_mask(&previous_signal_mask);
        (void)close(socket_fd);
        free(worker);
        return 0;
    }
    worker->next = service->workers;
    service->workers = worker;
    ++service->active_workers;
    (void)pthread_mutex_unlock(&service->worker_lock);
    if (pthread_attr_init(&attributes) != 0) {
        (void)authorization_restore_signal_mask(&previous_signal_mask);
        authorization_worker_release(worker);
        return -1;
    }
    result = pthread_attr_setdetachstate(&attributes, PTHREAD_CREATE_DETACHED);
    if (result == 0) {
        result = pthread_create(&thread, &attributes, authorization_worker_main, worker);
        worker_created = result == 0;
    }
    (void)pthread_attr_destroy(&attributes);
    if (!authorization_restore_signal_mask(&previous_signal_mask)) {
        if (worker_created) {
            /* pthread_sigmask() with a previously valid mask should not fail.
             * If it does, keep the worker alive and make the serving thread
             * explicitly unblocked so shutdown remains signal-driven. */
            (void)authorization_unblock_termination_signals();
            return 1;
        }
        (void)authorization_unblock_termination_signals();
    }
    if (result != 0) {
        authorization_worker_release(worker);
        return -1;
    }
    return 1;
}

static void authorization_shutdown_workers(authorization_service *service) {
    if (service == NULL || pthread_mutex_lock(&service->worker_lock) != 0) {
        return;
    }
    for (authorization_worker *worker = service->workers;
        worker != NULL; worker = worker->next) {
        (void)shutdown(worker->socket_fd, SHUT_RDWR);
    }
    (void)pthread_mutex_unlock(&service->worker_lock);
}

static int authorization_wait_for_workers(
    authorization_service *service,
    unsigned long timeout_ms) {
    struct timespec deadline;
    int result;
    int workers_finished;
    if (service == NULL || timeout_ms == 0UL ||
        clock_gettime(CLOCK_REALTIME, &deadline) != 0 ||
        pthread_mutex_lock(&service->worker_lock) != 0) {
        return 0;
    }
    deadline.tv_sec += (time_t)(timeout_ms / 1000UL);
    deadline.tv_nsec += (long)((timeout_ms % 1000UL) * 1000000UL);
    if (deadline.tv_nsec >= 1000000000L) {
        ++deadline.tv_sec;
        deadline.tv_nsec -= 1000000000L;
    }
    result = 0;
    while (service->active_workers > 0UL && result == 0) {
        result = pthread_cond_timedwait(
            &service->workers_idle, &service->worker_lock, &deadline);
    }
    workers_finished = result == 0 && service->active_workers == 0UL;
    if (pthread_mutex_unlock(&service->worker_lock) != 0) {
        return 0;
    }
    return workers_finished;
}

/*
 * After both bounded shutdown waits expire, the service must remain alive for
 * its detached workers. The final worker performs the release; if it won the
 * race before this function acquired the lock, the caller retains ownership
 * and releases the service synchronously instead.
 */
static int authorization_defer_cleanup(authorization_service *service) {
    int deferred = 0;
    if (service == NULL || pthread_mutex_lock(&service->worker_lock) != 0) {
        /* Ownership is uncertain: leaking this process-local service is safer
         * than destroying state a detached worker may still reference. */
        return -1;
    }
    if (service->active_workers > 0UL) {
        service->deferred_cleanup = 1;
        deferred = 1;
    }
    (void)pthread_mutex_unlock(&service->worker_lock);
    return deferred;
}

static int authorization_mark_response_companion_quiesced(
    authorization_service *service) {
    int release_service = 0;

    if (service == NULL || pthread_mutex_lock(&service->worker_lock) != 0) {
        return -1;
    }
    service->response_companion_quiesced = 1;
    if (service->active_workers == 0UL) {
        if (service->deferred_cleanup && !service->release_claimed) {
            service->deferred_cleanup = 0;
            service->release_claimed = 1;
            release_service = 1;
        } else if (!service->deferred_cleanup && !service->release_claimed) {
            service->release_claimed = 1;
            release_service = 1;
        }
    } else {
        service->deferred_cleanup = 1;
    }
    (void)pthread_mutex_unlock(&service->worker_lock);
    return release_service;
}

static int authorization_shutdown_response_companion(
    const msconnector_http_authorization_profile *profile) {
    msconnector_error error;

    if (profile == NULL || profile->shutdown_response_companion == NULL) {
        return 1;
    }
    msconnector_error_init(&error);
    return profile->shutdown_response_companion(
        profile->response_companion_userdata, &error);
}

static int authorization_defer_uninterruptible_worker(
    authorization_service *service,
    const msconnector_http_authorization_profile *profile)
{
    if (authorization_defer_cleanup(service) == 0) {
        return 0;
    }
    /* A profile without a response companion cannot have handed a transaction
     * to an external observer. Its final worker may release after returning
     * from an uninterruptible runtime call. Configured companions remain
     * quarantined until their shutdown callback has quiesced successfully. */
    if (profile->shutdown_response_companion == NULL &&
        authorization_mark_response_companion_quiesced(service) > 0) {
        authorization_service_release(service);
    }
    return 1;
}

static authorization_listener_iteration authorization_wait_for_listener(
    int listener,
    const char *connector_name) {
    struct pollfd listener_descriptor;
    int listener_ready;
    memset(&listener_descriptor, 0, sizeof(listener_descriptor));
    listener_descriptor.fd = listener;
    listener_descriptor.events = POLLIN;
    do {
        listener_ready = poll(&listener_descriptor, 1U,
            AUTH_LISTENER_POLL_TIMEOUT_MS);
    } while (listener_ready < 0 && errno == EINTR && !authorization_stop);
    if (listener_ready == 0) {
        return AUTHORIZATION_LISTENER_RETRY;
    }
    if (authorization_stop) {
        return AUTHORIZATION_LISTENER_STOP;
    }
    if (listener_ready < 0 || (listener_descriptor.revents & POLLIN) == 0) {
        (void)fprintf(stderr, "%s listener poll failed: %s\n",
            connector_name,
            listener_ready < 0 ? strerror(errno) : "unexpected listener state");
        return AUTHORIZATION_LISTENER_ERROR;
    }
    return AUTHORIZATION_LISTENER_READY;
}

static authorization_listener_iteration authorization_serve_next_connection(
    authorization_service *service,
    int listener,
    const struct sockaddr_in *local) {
    struct sockaddr_in peer = {0};
    socklen_t peer_size = sizeof(peer);
    connection_deadline read_deadline;
    authorization_listener_iteration listener_state =
        authorization_wait_for_listener(listener, service->profile->connector_name);
    int client_fd;
    if (listener_state != AUTHORIZATION_LISTENER_READY) {
        return listener_state;
    }
    do {
        client_fd = accept(listener, (struct sockaddr *)&peer, &peer_size);
    } while (client_fd < 0 && errno == EINTR && !authorization_stop);
    if (client_fd < 0) {
        if (authorization_stop) {
            return AUTHORIZATION_LISTENER_STOP;
        }
        (void)fprintf(stderr, "%s accept failed: %s\n",
            service->profile->connector_name, strerror(errno));
        return AUTHORIZATION_LISTENER_ERROR;
    }
    if (!connection_deadline_init(
            &read_deadline, service->connection_timeout_ms) ||
        !configure_client_socket(client_fd)) {
        (void)fprintf(stderr, "%s client socket deadline setup failed: %s\n",
            service->profile->connector_name, strerror(errno));
        (void)close(client_fd);
        return AUTHORIZATION_LISTENER_HANDLED;
    }
    {
        const int worker_result = authorization_start_worker(
            service, client_fd, &peer, local, &read_deadline);
        if (worker_result < 0) {
            (void)fprintf(stderr, "%s worker start failed\n",
                service->profile->connector_name);
        } else if (worker_result == 0) {
            (void)fprintf(stderr, "%s worker admission limit reached; "
                "connection closed fail-closed\n",
                service->profile->connector_name);
        }
    }
    return AUTHORIZATION_LISTENER_HANDLED;
}

static int authorization_serve_requests(
    authorization_service *service,
    int listener,
    const struct sockaddr_in *local,
    unsigned long max_requests) {
    unsigned long handled = 0UL;
    while (!authorization_stop && (max_requests == 0UL || handled < max_requests)) {
        const authorization_listener_iteration listener_state =
            authorization_serve_next_connection(service, listener, local);
        if (listener_state == AUTHORIZATION_LISTENER_ERROR) {
            return 1;
        }
        if (listener_state == AUTHORIZATION_LISTENER_STOP) {
            return 0;
        }
        if (listener_state == AUTHORIZATION_LISTENER_HANDLED) {
            ++handled;
        }
    }
    return 0;
}

static int authorization_handle_worker_timeout(
    authorization_service *service,
    const msconnector_http_authorization_profile *profile,
    unsigned long timeout_ms) {
    (void)fprintf(stderr, "%s worker shutdown grace period expired; "
        "forcing socket cancellation\n", profile->connector_name);
    authorization_shutdown_workers(service);
    if (authorization_wait_for_workers(service, timeout_ms)) {
        return 0;
    }
    (void)fprintf(stderr, "%s worker shutdown did not complete; "
        "runtime call may be uninterruptible\n", profile->connector_name);
    return authorization_defer_uninterruptible_worker(service, profile);
}

static int serve_authorization(
    const authorization_cli *cli,
    const msconnector_http_authorization_profile *profile) {
    msconnector_runtime *runtime = NULL;
    authorization_service *service = NULL;
    struct sockaddr_in local = {0};
    int listener = -1;
    int service_status = 0;
    char error[AUTH_ERROR_SIZE];
    struct sigaction action;

    error[0] = '\0';
    if (!msconnector_runtime_create(profile->connector_name, cli->config_path,
            &runtime, error, sizeof(error))) {
        (void)fprintf(stderr, "%s config/start failed: %s\n",
            profile->connector_name, error);
        return 1;
    }
    if (!msconnector_runtime_set_event_integration_mode(runtime,
            profile->integration_mode)) {
        (void)fprintf(stderr, "%s integration-mode setup failed\n",
            profile->connector_name);
        msconnector_runtime_destroy(&runtime);
        return 1;
    }
    if (!msconnector_runtime_set_transaction_profile(runtime,
            profile->transaction_profile)) {
        (void)fprintf(stderr, "%s transaction-profile setup failed\n",
            profile->connector_name);
        msconnector_runtime_destroy(&runtime);
        return 1;
    }
    service = calloc(1U, sizeof(*service));
    if (service == NULL ||
        !authorization_service_init(service, runtime, profile, cli)) {
        (void)fprintf(stderr, "%s service synchronization setup failed\n",
            profile->connector_name);
        free(service);
        msconnector_runtime_destroy(&runtime);
        return 1;
    }
    if (!create_listener(cli->listen_spec, &listener, &local, error, sizeof(error))) {
        (void)fprintf(stderr, "%s service start failed: %s\n",
            profile->connector_name, error);
        (void)authorization_service_release(service);
        return 1;
    }
    memset(&action, 0, sizeof(action));
    action.sa_handler = stop_service;
    (void)sigemptyset(&action.sa_mask);
    (void)sigaction(SIGTERM, &action, NULL);
    (void)sigaction(SIGINT, &action, NULL);
    (void)printf("connector=%s integration_mode=%s listen=%s status=ready\n",
        profile->connector_name, profile->integration_mode, cli->listen_spec);
    (void)fflush(stdout);
    service_status = authorization_serve_requests(
        service, listener, &local, cli->max_requests);
    if (listener >= 0) {
        (void)close(listener);
    }
    if (authorization_stop || service_status != 0) {
        authorization_shutdown_workers(service);
    }
    /* A socket shutdown cannot interrupt an uninterruptible call into
     * libmodsecurity.  Give workers one bounded grace period, then close
     * their sockets and wait once more.  If a worker still owns the
     * runtime, leave the service/runtime allocated and return: the main
     * process exits with a defined failure status instead of creating a
     * use-after-free by destroying objects still referenced by a worker.
     */
    if (!authorization_wait_for_workers(service, cli->connection_timeout_ms) &&
        authorization_handle_worker_timeout(service, profile,
            cli->connection_timeout_ms)) {
        return 1;
    }
    if (!authorization_shutdown_response_companion(profile)) {
        (void)fprintf(stderr, "%s response companion did not quiesce; refusing runtime destruction\n",
            profile->connector_name);
        /* Keep the service and runtime quarantined: the companion may still
         * reference live transaction state, so neither teardown nor process
         * termination is safe on this failure path. */
        return service_status != 0 ? service_status : 1;
    }
    if (authorization_mark_response_companion_quiesced(service) > 0) {
        authorization_service_release(service);
    }
    return service_status;
}

int msconnector_http_authorization_service_main(
    int argc,
    char **argv,
    const msconnector_http_authorization_profile *profile) {
    authorization_cli cli;
    char error[AUTH_ERROR_SIZE];
    if (!validate_profile(profile) || !parse_cli(argc, argv, &cli)) {
        print_usage(argc > 0 && argv != NULL ? argv[0] : "authorization-service");
        return 2;
    }
    if (cli.check_config) {
        error[0] = '\0';
        if (!msconnector_runtime_config_check(profile->connector_name,
                cli.config_path, error, sizeof(error))) {
            (void)fprintf(stderr, "%s config invalid: %s\n",
                profile->connector_name, error);
            return 1;
        }
        (void)printf("connector=%s integration_mode=%s config_status=valid\n",
            profile->connector_name, profile->integration_mode);
        return 0;
    }
    return serve_authorization(&cli, profile);
}
